        // 仅有上下文卡片处于 collecting 时隐藏 Goal LiveStrip，避免在 Goal 与子卡片重复展示；
        // 无执行会话但有 status_line 时退化为独立状态行（带动画）
        g.attempt_child_id && (g.status === "in_progress" || hasActiveGoalExecutionAttempt(g.attempts))
